parameters.jsCode:
// Grab the reasoning node's structured output.
// It usually sits under `output`; fall back to the item itself just in case.
const item = $input.first().json;
const r = item.output || item;

// Map each edge role to a Mermaid arrow style so the diagram
// visually distinguishes causal / confounder / mediator / collider.
const roleArrow = {
  causal:     "-->",
  confounder: "-.->",
  mediator:   "==>",
  collider:   "-.->"
};

// Mermaid node IDs can't contain spaces or punctuation, so sanitise.
const clean = s => String(s).replace(/[^a-zA-Z0-9]/g, "_");

// Build the Mermaid diagram string, one line per node then per edge.
let mermaid = "graph LR\n";
for (const n of r.dag.nodes) {
  mermaid += `  ${clean(n)}["${n}"]\n`;
}
for (const e of r.dag.edges) {
  const arrow = roleArrow[e.role] || "-->";
  mermaid += `  ${clean(e.from)} ${arrow}|${e.role}| ${clean(e.to)}\n`;
}

// Turn the 1-5 score into a star bar.
const score = r.causal_support;
const stars = "★".repeat(score) + "☆".repeat(5 - score);

// Assemble a readable verdict block in Markdown.
const summary = `## Causal Claim Audit

**Verdict:** ${r.verdict}

**Causal support:** ${stars} (${score}/5)

**Strongest design:** ${r.strongest_design}

**Primary threat:** ${r.primary_threat}

**What would upgrade it:** ${r.what_would_upgrade_it}

### Reasoning
- **Design ceiling:** ${r.reasoning.design_ceiling}
- **Confounding:** ${r.reasoning.confounding}
- **Collider / mediator:** ${r.reasoning.collider_mediator}
- **Consistency:** ${r.reasoning.consistency}
- **Temporality:** ${r.reasoning.temporality}

### Causal DAG
\`\`\`mermaid
${mermaid}\`\`\`
`;

return [{ json: { summary, mermaid, verdict: r.verdict, causal_support: score } }];

