const input = $input.first().json;
const raw = (input.body?.claim ?? '').toString().trim();
const key = raw.toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
const valid = raw.length >= 5 && raw.length <= 200;

const store = $getWorkflowStaticData('global');
store.cache = store.cache || {};
const hit = valid ? store.cache[key] : null;
const fresh = !!hit && (Date.now() - hit.t) < 30 * 24 * 3600 * 1000;

if (fresh) {
  const r = hit.r;
  // same shape as a fresh answer: summary, verdict, score, mermaid
  return [{ json: {
    summary: r.summary,
    verdict: r.verdict,
    score: r.score ?? r.causal_support,
    mermaid: r.mermaid,
    cached: true,
    valid: true
  } }];
}
return [{ json: { ...input, cacheKey: key, valid, cached: false } }];

const store = $getWorkflowStaticData('global');
store.cache = store.cache || {};
const key = $('Check cache').first().json.cacheKey;
const result = $input.first().json;

store.cache[key] = { t: Date.now(), r: result };

// keep only the 200 most recent claims
const keys = Object.keys(store.cache);
if (keys.length > 200) {
  keys.sort((a, b) => store.cache[a].t - store.cache[b].t)
      .slice(0, keys.length - 200)
      .forEach(k => delete store.cache[k]);
}
return [{ json: result }];
